int[] mergeSort(int[] arr) {
    if (arr.length <= 1) return arr;
    auto mid = arr.length / 2;
    return merge(mergeSort(arr[0 .. mid]), mergeSort(arr[mid .. $]));
}

int[] merge(int[] left, int[] right) {
    int[] result;
    int i = 0, j = 0;
    while (i < cast(int) left.length && j < cast(int) right.length) {
        if (left[i] <= right[j]) {
            result ~= left[i];
            i++;
        } else {
            result ~= right[j];
            j++;
        }
    }
    result ~= left[i .. $];
    result ~= right[j .. $];
    return result;
}

