sub merge {
    my ($left, $right) = @_;
    my @result;
    my ($i, $j) = (0, 0);
    while ($i < @$left && $j < @$right) {
        if ($left->[$i] <= $right->[$j]) {
            push @result, $left->[$i++];
        } else {
            push @result, $right->[$j++];
        }
    }
    push @result, @$left[$i .. $#$left];
    push @result, @$right[$j .. $#$right];
    return \@result;
}

