#include <vector>
#include <stack>

vector<int> dfs(vector<vector<int>>& graph, int start) {
    int n = graph.size();
    vector<bool> visited(n, false);
    vector<int> order;
    stack<int> stk;
    stk.push(start);
    while (!stk.empty()) {
        int node = stk.top();
        stk.pop();
        if (visited[node]) continue;
        visited[node] = true;
        order.push_back(node);
        for (int i = graph[node].size() - 1; i >= 0; i--) {
            int neighbor = graph[node][i];
            if (!visited[neighbor]) {
                stk.push(neighbor);
            }
        }
    }
    return order;
}

