#include <queue>

vector<int> topologicalSort(vector<vector<int>>& graph, int n) {
    vector<int> inDegree(n, 0);
    for (int u = 0; u < n; u++)
        for (int v : graph[u])
            inDegree[v]++;
    queue<int> q;
    for (int v = 0; v < n; v++)
        if (inDegree[v] == 0)
            q.push(v);
    vector<int> order;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        order.push_back(u);
        for (int v : graph[u]) {
            inDegree[v]--;
            if (inDegree[v] == 0)
                q.push(v);
        }
    }
    return order;
}

