func topologicalSort(graph: [[Int]], n: Int) -> [Int] {
    var inDegree = Array(repeating: 0, count: n)
    for u in 0..<n {
        for v in graph[u] {
            inDegree[v] += 1
        }
    }
    var queue: [Int] = []
    for v in 0..<n {
        if inDegree[v] == 0 {
            queue.append(v)
        }
    }
    var order: [Int] = []
    var front = 0
    while front < queue.count {
        let u = queue[front]
        front += 1
        order.append(u)
        for v in graph[u] {
            inDegree[v] -= 1
            if inDegree[v] == 0 {
                queue.append(v)
            }
        }
    }
    return order
}

