using System;
using System.Collections.Generic;

class TopologicalSort {
    static List<int> Sort(List<int>[] graph, int n) {
        int[] inDegree = new int[n];
        for (int u = 0; u < n; u++)
            foreach (int v in graph[u])
                inDegree[v]++;
        Queue<int> queue = new Queue<int>();
        for (int v = 0; v < n; v++)
            if (inDegree[v] == 0)
                queue.Enqueue(v);
        List<int> order = new List<int>();
        while (queue.Count > 0) {
            int u = queue.Dequeue();
            order.Add(u);
            foreach (int v in graph[u]) {
                inDegree[v]--;
                if (inDegree[v] == 0)
                    queue.Enqueue(v);
            }
        }
        return order;
    }

}

