sub build_lps {
    my ($pattern) = @_;
    my $p_len = length($pattern);
    my @lps = (0) x $p_len;
    my $len = 0;
    my $i = 1;
    while ($i < $p_len) {
        if (substr($pattern, $i, 1) eq substr($pattern, $len, 1)) {
            $len++;
            $lps[$i] = $len;
            $i++;
        } else {
            if ($len != 0) {
                $len = $lps[$len - 1];
            } else {
                $lps[$i] = 0;
                $i++;
            }
        }
    }
    return \@lps;
}

sub kmp_search {
    my ($text, $pattern) = @_;
    my $lps = build_lps($pattern);
    my @results;
    my ($i, $j) = (0, 0);
    my $t_len = length($text);
    my $p_len = length($pattern);
    while ($i < $t_len) {
        if (substr($text, $i, 1) eq substr($pattern, $j, 1)) {
            $i++;
            $j++;
        }
        if ($j == $p_len) {
            push @results, $i - $j;
            $j = $lps->[$j - 1];
        } elsif ($i < $t_len && substr($text, $i, 1) ne substr($pattern, $j, 1)) {
            if ($j != 0) {
                $j = $lps->[$j - 1];
            } else {
                $i++;
            }
        }
    }
    return \@results;
}

